}

const built = config.build(args || {});
const text = clean(built.text);
if (!text) {
  return [{ json: { ok: false, error: `Unsupported or invalid tool request: ${tool}` } }];
}

return [{
  json: {
    ok: true,
    tool,
    workflowKey: config.workflowKey,
    workflowLookup: Boolean(config.workflowLookup),
    workflowName: config.workflowName || '',
    text,
    rawText: text,
    chatId: backendChatId,
    originChatId,
    userId,
    requestId,
    deliveryMode,
    args,
    payload: { tool, args, requestId, originChatId, userId, deliveryMode },
    message: { text, caption: text },
    ...built,
  }
}];

const source = $('Prepare Tool Request').item.json || {};
const output = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const raw = String(
  output.text ||
  output.output ||
  output.response ||
  output.responseText ||
  ''
).replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

const text = htmlToPlainText(raw) || raw || JSON.stringify(output);

return [{
  json: {
    ok: output.ok !== false,
    tool: source.tool || '',
    workflowKey: source.workflowKey || '',
    requestId: source.requestId || '',
    text,
    data: output,
  }
}];

const workflows = $input.item.json.data;
const routed = $('Route Tool').item.json || {};
const targetName = routed.workflowName;
const found = Array.isArray(workflows) ? workflows.find((w) => w.name === targetName) : null;
if (!found) {
  return [{ json: { ...routed, ok: false, workflowId: '', error: 'Workflow not found: ' + targetName, text: 'Khong tim thay workflow con: ' + targetName } }];
}
return [{ json: { ...routed, workflowId: found.id } }];
